"args\": {\"degree\": \"int\", \"group\": \"group\"}, \"families\": [\"explicit\", \"subsets\", \"subsets_of\"], \"name\": \"is_regular_of_degree\", \"summary\": \"Whether every vertex has exactly `degree` neighbours in the simple undirected Cayley graph.\", \"value\": \"boolean\"}, {\"args\": {\"group\": \"group\"}, \"families\": [\"explicit\", \"subsets\", \"subsets_of\"], \"name\": \"girth\", \"summary\": \"Length of a shortest cycle, or 0 for an acyclic graph, matching Mathlib SimpleGraph.girth.\", \"value\": \"integer\"}, {\"args\": {\"group\": \"group\"}, \"families\": [\"explicit\", \"subsets\", \"subsets_of\"], \"name\": \"diameter\", \"summary\": \"Maximum shortest-path distance when connected, or 0 when disconnected, matching Mathlib SimpleGraph.diam.\", \"value\": \"integer\"}, {\"args\": {\"group\": \"group\"}, \"families\": [\"explicit\", \"subsets\", \"subsets_of\"], \"name\": \"aut_order\", \"summary\": \"Order of the full automorphism group of the unlabelled graph, counted by equitable partition refinement and individualisation.\", \"value\": \"integer\"}, {\"args\": {\"group\": \"group\"}, \"families\": [\"explicit\", \"subsets\", \"subsets_of\"], \"name\": \"is_ci_set\", \"summary\": \"Whether S is inverse-closed and every inverse-closed identity-free T of the same size with Cay(G,T) isomorphic to Cay(G,S) is an Aut(G)-image of S. Non-inverse-closed S returns false.\", \"value\": \"boolean\"}], \"rejections\": [{\"case\": \"matrix group is unsupported\", \"error\": \"permutation group\"}, {\"case\": \"identity is not a connection\", \"error\": \"identity\"}, {\"case\": \"element outside G\", \"error\": \"not an element\"}, {\"case\": \"range is not a connection family\", \"error\": \"families only\"}, {\"case\": \"C4 singletons\", \"error\": \"does not accept integer\", \"op\": \"girth\", \"reduction\": \"count\"}]}, {\"backends\": [{\"accepts\": \"block families with canonical standard-basis block members; permutation groups for Kramer-Mesner matrices\", \"name\": \"generic\", \"sources\": [\"backends/generic/designs_generic.cpp\"], \"summary\": \"Portable C++: one pass for incidence counts and intersections, canonical exact-cover search for resolutions, and subset-orbit closure for Kramer-Mesner matrices.\"}], \"kinds\": [{\"lean\": \"matrix\", \"name\": \"designs.matrix\", \"params\": [\"count\", \"rows\", \"cols\"], \"payload\": \"count*rows*cols u64 entries, row-major, little-endian\", \"summary\": \"A batch of fixed-shape natural-number matrices with 64-bit entries. Design operations return one matrix.\"}], \"module\": {\"cases\": \"cases.py\", \"contract\": \"lean/Designs/Contract.lean\", \"lean\": \"lean\", \"naive\": \"naive/naive.py\", \"name\": \"designs\", \"reference\": \"lean/Designs/Reference.lean\", \"summary\": \"Finite block designs represented by families of canonical point-subset matrices: t-design tests and lambda vectors, resolutions, dual 2-designs, block-intersection distributions, and canonical Kramer-Mesner matrices.\", \"version\": 1}, \"operations\": [{\"args\": {\"t\": \"int\"}, \"name\": \"is_design\", \"summary\": \"For the whole block family, return [[flag, lambda_0]], where flag says every t-subset occurs equally often and lambda_0 is the multiplicity of the lexicographically first t-subset. Blocks are k x v matrices whose rows are distinct standard basis vectors in increasing point order.\", \"value\": \"designs.matrix\"}, {\"args\": {\"t\": \"int\"}, \"name\": \"lambda_vector\", \"summary\": \"For the whole block family, return one row containing the multiplicity of every t-subset of {0,...,v-1}, in lexicographic subset order.\", \"value\": \"designs.matrix\"}, {\"name\": \"is_resolvable\", \"summary\": \"Return the lexicographically least resolution witness as a matrix of block indices, one parallel class per row and indices increasing within each row; return the unique empty 0 x 0 matrix when no resolution exists.\", \"value\": \"designs.matrix\"}, {\"name\": \"dual_is_design\", \"summary\": \"Return [[flag, lambda_0]] for whether the dual incidence structure is a 2-design; lambda_0 is the intersection size of the first two indexed blocks.\", \"value\": \"designs.matrix\"}, {\"name\": \"intersection_numbers\", \"summary\": \"Return one row h[0..k], where h[j] is the number of unordered pairs of distinct indexed blocks with intersection size j.\", \"value\": \"designs.matrix\"}, {\"args\": {\"group\": \"group\", \"t\": \"int\"}, \"families\": [\"subsets\"], \"name\": \"kramer_mesner_matrix\", \"summary\": \"For a group on the dictionary positions of the k-subsets family, return the Kramer-Mesner matrix. Rows and columns are t-subset and k-subset orbits ordered by their least lexicographic member; entry (i,j) counts blocks in column orbit j containing the least member of row orbit i.\", \"value\": \"designs.matrix\"}], \"rejections\": [{\"case\": \"malformed repeated point\", \"error\": \"distinct standard basis\"}, {\"case\": \"Kramer-Mesner with a matrix group\", \"error\": \"permutation\"}]}, {\"backends\": [{\"accepts\": \"any p < 2^32; any family; any operation\", \"name\": \"generic\", \"sources\": [\"backends/generic/gfp_generic.cpp\"], \"summary\": \"Portable C++: depth-first enumeration with an incremental echelon basis shared along each prefix, subtree pruning, threads over top-level branches.\"}], \"kinds\": [{\"lean\": \"matrix\", \"name\": \"gfp.matrix\", \"params\": [\"p\", \"count\", \"rows\", \"cols\"], \"payload\": \"count*rows*cols entries\", \"summary\": \"A batch of `count` matrices, each rows x cols over F_p. Vectors are 1 x n matrices.\"}, {\"lean\": \"basis\", \"name\": \"gfp.basis\", \"params\": [\"p\", \"count\", \"cols\"], \"payload\": \"u64 offsets[count+1], then entries of offsets[count] row vectors of length cols\", \"summary\": \"For each of `count` members, a list of row vectors (ragged).\"}, {\"lean\": \"solution\", \"name\": \"gfp.solutions\", \"params\": [\"p\", \"count\", \"length\"], \"payload\": \"u8 solvable[count], then count*length entries\", \"summary\": \"Per member: a flag and a solution vector (zeros when unsolvable).\"}, {\"lean\": \"inverse\", \"name\": \"gfp.inverses\", \"params\": [\"p\", \"count\", \"n\"], \"payload\": \"u8 invertible[count], then count*n*n entries\", \"summary\": \"Per member: a flag and the inverse (zeros when singular).\"}, {\"lean\": \"witness\", \"name\": \"gfp.witness\", \"params\": [\"p\", \"count\", \"rows\", \"cols\"], \"payload\": \"count*rows*cols entries of R, then count*rows*rows entries of T\", \"summary\": \"Per member A: its rref R and an invertible T with T*A = R.\"}], \"module\": {\"cases\": \"cases.py\", \"contract\": \"lean/Gfp/Contract.lean\", \"lean\": \"lean\", \"naive\": \"naive/naive.py\", \"name\": \"gfp\", \"reference\": \"lean/Gfp/Reference.lean\", \"summary\": \"Linear algebra over F_p (p prime) on families of matrices: rref, rank, nullspace, solve, inverse, span membership.\", \"version\": 1}, \"operations\": [{\"name\": \"rank\", \"summary\": \"Rank of the member.\", \"value\": \"integer\"}, {\"name\": \"nullity\", \"summary\": \"cols - rank.\", \"value\": \"integer\"}, {\"name\": \"full_row_rank\", \"summary\": \"rank == rows.\", \"value\": \"boolean\"}, {\"name\": \"full_col_rank\", \"summary\": \"rank == cols.\", \"value\": \"boolean\"}, {\"args\": {\"target\": \"vector\"}, \"name\": \"in_span\", \"summary\": \"The 1 x cols matrix `target` lies in the row space of the member.\", \"value\": \"boolean\"}, {\"name\": \"rref\", \"summary\": \"Reduced row echelon form of the member.\", \"value\": \"gfp.matrix\"}, {\"name\": \"nullspace\", \"summary\": \"Canonical basis of {x : M x^T = 0}: one vector per free column f of rref(M), in increasing f, with x_f = 1, x_pivot_i = -R[i][f], zeros elsewhere.\", \"value\": \"gfp.basis\"}, {\"args\": {\"rhs\": \"vectors\"}, \"families\": [\"explicit\"], \"name\": \"solve\", \"summary\": \"For member A_i and rhs vector b_i (1 x rows): x with A_i x^T = b_i^T, free coordinates zero; flag 0 when none exists.\", \"value\": \"gfp.solutions\"}, {\"families\": [\"explicit\"], \"name\": \"inverse\", \"summary\": \"Inverse of a square member; flag 0 when singular.\", \"value\": \"gfp.inverses\"}, {\"families\": [\"explicit\"], \"name\": \"rref_witness\", \"summary\": \"rref R and the transform T of Gauss-Jordan elimination with first-nonzero-row pivoting, so T*A = R with T invertible.\", \"value\": \"gfp.witness\"}], \"rejections\": [{\"case\": \"grassmannian F_2\", \"error\": \"does not accept integer\", \"op\": \"rank\", \"reduction\": \"count\"}, {\"case\": \"grassmannian F_2\", \"error\": \"does not accept\", \"op\": \"rref\", \"reduction\": \"histogram\"}, {\"case\": \"grassmannian F_2\", \"error\": \"does not accept\", \"op\": \"nullspace\", \"reduction\": \"count\"}, {\"case\": \"grassmannian F_2\", \"error\": \"explicit families only\", \"op\": \"inverse\"}, {\"case\": \"grassmannian F_2\", \"error\": \"explicit families only\", \"op\": \"rref_witness\"}]}, {\"backends\": [{\"accepts\": \"any F_2 matrix family; canonical_form enumerates row permutations and chooses the best column order\", \"name\": \"generic\", \"sources\": [\"backends/generic/hadamard_generic.cpp\"], \"summary\": \"Portable C++: threaded member evaluation; sign dot products use bit equality, and canonical forms enumerate row orders while sorting normalised columns.\"}], \"module\": {\"cases\": \"cases.py\", \"contract\": \"lean/Hadamard/Contract.lean\", \"lean\": \"lean\", \"naive\": \"naive/naive.py\", \"name\": \"hadamard\", \"reference\": \"lean/Hadamard/Reference.lean\", \"summary\": \"Hadamard, skew, regular and conference tests for F_2 matrices read as signs (0 = +1, 1 = -1), plus the lexicographically least form under signed row and column permutations.\", \"version\": 1}, \"operations\": [{\"name\": \"is_hadamard\", \"summary\": \"Whether the member is square and its sign lift H satisfies H H^T = n I.\", \"value\": \"boolean\"}, {\"name\": \"is_skew\", \"summary\": \"Whether the member is square and its sign lift H satisfies H + H^T = 2 I. This tests skew type and does not also require the Hadamard property.\", \"value\": \"boolean\"}, {\"name\": \"is_regular\", \"summary\": \"Whether the member is square and every row sum and every column sum of its sign lift are one common integer.\", \"value\": \"boolean\"}, {\"name\": \"is_conference\", \"summary\": \"Whether n >= 2, every diagonal bit is 0, and replacing that +1 diagonal by zero gives C C^T = (n-1) I. Requiring diagonal bits 0 makes the encoding unique.\", \"value\": \"boolean\"}, {\"name\": \"canonical_form\", \"summary\": \"The row-major lexicographically least F_2 matrix obtainable by permuting and independently negating rows and columns. Bits use 0 = +1 and 1 = -1.\", \"value\": \"gfp.matrix\"}], \"rejections\": [{\"case\": \"ternary sign input\", \"error\": \"no available backend accepts\", \"op\": \"is_hadamard\"}, {\"case\": \"ternary sign input\", \"error\": \"no available backend accepts\", \"op\": \"is_skew\"}, {\"case\": \"ternary sign input\", \"error\": \"no available backend accepts\", \"op\": \"is_regular\"}, {\"case\": \"ternary sign input\", \"error\": \"no available backend accepts\", \"op\": \"is_conference\"}, {\"case\": \"ternary sign input\", \"error\": \"no available backend accepts\", \"op\": \"canonical_form\"}, {\"case\": \"canonical form with count\", \"error\": \"does not accept\", \"op\": \"canonical_form\", \"reduction\": \"count\"}]}, {\"backends\": [{\"accepts\": \"any group given by generators; orbits computed by breadth-first search per member; group order by closure up to 2^26 elements\", \"name\": \"generic\", \"sources\": [\"backends/generic/orbits_generic.cpp\"], \"summary\": \"Portable C++: per-member orbit BFS over the generators with index ranking through the family's unrank/rank, threaded over members; fixed_points on subsets by cycle type (coefficient of x^k in the product of 1 + x^len over cycles). No orderly-generation pruning yet.\"}], \"kinds\": [{\"lean\": \"perm\", \"name\": \"orbits.perms\", \"params\": [\"n\", \"count\"], \"payload\": \"count*n u32 point indices; element g maps point i to entry g*n+i\", \"summary\": \"A batch of `count` permutations of {0..n-1}. As a group argument, the generators.\"}], \"module\": {\"cases\": \"cases.py\", \"contract\": \"lean/Orbits/Contract.lean\", \"lean\": \"lean\", \"naive\": \"naive/naive.py\", \"name\": \"orbits\", \"reference\": \"lean/Orbits/Reference.lean\", \"summary\": \"Finite permutation and matrix groups acting on families: canonical representatives, orbit sizes, stabilisers, fixed points (Burnside), induced point actions.\", \"version\": 1}, \"operations\": [{\"args\": {\"group\": \"group\"}, \"families\": [\"subsets\", \"subsets_of\", \"grassmannian\", \"all_matrices\"], \"name\": \"is_canonical\", \"summary\": \"The member has the least index in its orbit under `group`. With `hits`, the orbit transversal; with `count`, the number of orbits.\", \"value\": \"boolean\"}, {\"args\": {\"group\": \"group\"}, \"families\": [\"subsets\", \"subsets_of\", \"grassmannian\", \"all_matrices\"], \"name\": \"canonical_index\", \"summary\": \"The least index in the member's orbit under `group`.\", \"value\": \"integer\"}, {\"args\": {\"group\": \"group\"}, \"families\": [\"subsets\", \"subsets_of\", \"grassmannian\", \"all_matrices\"], \"name\": \"orbit_size\", \"summary\": \"Number of members in the orbit of the member under `group`.\", \"value\": \"integer\"}, {\"args\": {\"group\": \"group\"}, \"families\": [\"subsets\", \"subsets_of\", \"grassmannian\", \"all_matrices\"], \"name\": \"stabilizer_order\", \"summary\": \"Order of the stabiliser of the member in `group`, i.e. |group| / orbit_size. Needs the group order, so `group` must generate a group the backend can enumerate.\", \"value\": \"integer\"}, {\"args\": {\"on\": \"family\"}, \"families\": [\"group_elements\"], \"name\": \"fixed_points\", \"summary\": \"For each group element, the number of members of the family `on` it fixes. Sum over the group divided by the group order is the number of orbits (Burnside), an independent check of is_canonical/count.\", \"value\": \"integer\"}, {\"args\": {\"points\": \"vectors\"}, \"families\": [\"explicit\"], \"name\": \"projective_action\", \"summary\": \"For each n x n matrix A of the batch, the permutation of the projective points `points` (a dictionary of 1 x n rows, each scaled so its first nonzero entry is 1, pairwise distinct) induced by v -> normalise(v A). Fails if the dictionary is not closed under some A. Bridges matrix groups to `subsets` families over projective points.\", \"value\": \"orbits.perms\"}], \"rejections\": [{\"case\": \"C5 on the hexagon\", \"error\": \"cannot act on a dictionary\"}, {\"case\": \"perms on a Grassmannian\", \"error\": \"subsets\"}, {\"case\": \"2x2 matrices on PG(2,2)\", \"error\": \"n x n\"}, {\"case\": \"singular matrix on PG(1,2)\", \"error\": \"singular\"}, {\"case\": \"points not closed\", \"error\": \"outside the dictionary\"}, {\"case\": \"D6 on 2-subsets\", \"error\": \"does not accept\", \"op\": \"is_canonical\", \"reduction\": \"histogram\"}, {\"case\": \"fixed_points on a subsets family\", \"error\": \"families\"}]}, {\"backends\": [{\"accepts\": \"subsets of coordinate rows over any prime p < 2^32; line and hyperplane incidence is precomputed once per request\", \"name\": \"generic\", \"sources\": [\"backends/generic/projective_sets_generic.cpp\"], \"summary\": \"Portable C++: precomputes dictionary incidence with every line or hyperplane, then evaluates members in parallel.\"}], \"module\": {\"cases\": \"cases.py\", \"contract\": \"lean/Projective_sets/Contract.lean\", \"lean\": \"lean\", \"naive\": \"naive/naive.py\", \"name\": \"projective_sets\", \"reference\": \"lean/Projective_sets/Reference.lean\", \"summary\": \"Point sets in PG(n,p), given as subsets of distinct normalised nonzero coordinate rows over F_p. Arc means every n+1 points are independent; cap means no three are collinear. Secant, tangent and passant counts range over every projective line.\", \"version\": 1}, \"operations\": [{\"families\": [\"subsets\"], \"name\": \"is_arc\", \"summary\": \"Whether every n+1 selected points of PG(n,p) are linearly independent, equivalently every hyperplane contains at most n points.\", \"value\": \"boolean\"}, {\"families\": [\"subsets\"], \"name\": \"is_cap\", \"summary\": \"Whether no projective line contains three selected points.\", \"value\": \"boolean\"}, {\"families\": [\"subsets\"], \"name\": \"is_blocking_set\", \"summary\": \"Whether the set meets every projective hyperplane.\", \"value\": \"boolean\"}, {\"families\": [\"subsets\"], \"name\": \"is_hyperoval\", \"summary\": \"Whether the set is a 4-point cap in PG(2,2), the only even field supported by the prime-field runtime.\", \"value\": \"boolean\"}, {\"families\": [\"subsets\"], \"name\": \"is_ovoid\", \"summary\": \"Whether the set is a cap of p^2+1 points in PG(3,p).\", \"value\": \"boolean\"}, {\"families\": [\"subsets\"], \"name\": \"max_collinear\", \"summary\": \"The largest intersection with a projective line; 0 when the ambient space has no lines.\", \"value\": \"integer\"}, {\"families\": [\"subsets\"], \"name\": \"spanned_rank\", \"summary\": \"Vector-space rank of the selected homogeneous coordinate rows, one more than the projective dimension of a nonempty span.\", \"value\": \"integer\"}, {\"families\": [\"subsets\"], \"name\": \"secant_count\", \"summary\": \"Number of projective lines containing exactly two selected points.\", \"value\": \"integer\"}, {\"families\": [\"subsets\"], \"name\": \"tangent_count\", \"summary\": \"Number of projective lines containing exactly one selected point.\", \"value\": \"integer\"}, {\"families\": [\"subsets\"], \"name\": \"passant_count\", \"summary\": \"Number of projective lines containing no selected point.\", \"value\": \"integer\"}], \"rejections\": [{\"case\": \"explicit point set\", \"error\": \"subsets\"}, {\"case\": \"zero projective point\", \"error\": \"contains zero\"}, {\"case\": \"unnormalised projective point\", \"error\": \"not normalised\"}, {\"case\": \"duplicate projective point\", \"error\": \"contains a duplicate\"}]}, {\"backends\": [{\"accepts\": \"Any p < 2^32 and Grassmannian-derived transform/stack family whose ambient Grassmannian size at each encountered rank fits u64; group closure up to 2^26 elements.\", \"name\": \"generic\", \"sources\": [\"backends/generic/subspace_orbits_generic.cpp\"], \"summary\": \"Portable C++: canonical rref and breadth-first orbit search per member, threaded over family members.\"}], \"module\": {\"cases\": \"cases.py\", \"contract\": \"lean/Subspace_orbits/Contract.lean\", \"lean\": \"lean\", \"naive\": \"naive/naive.py\", \"name\": \"subspace_orbits\", \"reference\": \"lean/Subspace_orbits/Reference.lean\", \"summary\": \"GL and projective linear orbits of Grassmannian families and their transform/stack derivatives. Representatives are the least rref subspaces in Grassmannian order. Set projective=0 for the generated GL group and projective=1 for its image modulo nonzero scalars. Over the runtime's prime fields, PGammaL equals PGL.\", \"version\": 1}, \"operations\": [{\"args\": {\"group\": \"group\", \"projective\": \"int\"}, \"families\": [\"grassmannian\", \"transform\", \"stack\"], \"name\": \"is_canonical\", \"summary\": \"Whether the member's row space is the least subspace in its orbit. Subspaces are ordered by their canonical rref's index in grassmannian(p, n, rank).\", \"value\": \"boolean\"}, {\"args\": {\"group\": \"group\", \"projective\": \"int\"}, \"families\": [\"grassmannian\", \"transform\", \"stack\"], \"name\": \"canonical_index\", \"summary\": \"Index of the least orbit representative in grassmannian(p, n, rank), where rank and n belong to this member's row space.\", \"value\": \"integer\"}, {\"args\": {\"group\": \"group\", \"projective\": \"int\"}, \"families\": [\"grassmannian\", \"transform\", \"stack\"], \"name\": \"orbit_size\", \"summary\": \"Number of distinct row spaces in the member's orbit. The projective flag does not change the orbit.\", \"value\": \"integer\"}, {\"args\": {\"group\": \"group\", \"projective\": \"int\"}, \"families\": [\"grassmannian\", \"transform\", \"stack\"], \"name\": \"stabilizer_order\", \"summary\": \"Order of the stabilizer: |generated GL group|/orbit_size when projective=0, or |its image modulo nonzero scalars|/orbit_size when projective=1.\", \"value\": \"integer\"}], \"rejections\": [{\"case\": \"permutations on subspaces\", \"error\": \"gfp.matrix\"}, {\"case\": \"all matrices are not a subspace family\", \"error\": \"families only\"}, {\"case\": \"wrong group dimension\", \"error\": \"n x n\"}, {\"case\": \"singular generator\", \"error\": \"invertible\"}, {\"case\": \"invalid projective flag\", \"error\": \"projective\"}]}], \"runtime\": {\"families\": [{\"lean\": \"explicit\", \"member\": \"gfp.matrix\", \"name\": \"explicit\", \"summary\": \"One member per matrix of the batch, in batch order.\"}, {\"lean\": \"subsets\", \"member\": \"gfp.matrix\", \"name\": \"subsets\", \"summary\": \"Every k-row matrix formed by choosing k rows of the dictionary, indices increasing; lexicographic order of the index tuple.\"}, {\"lean\": \"grassmannian\", \"member\": \"gfp.matrix\", \"name\": \"grassmannian\", \"summary\": \"Every h-dimensional subspace of F_p^n as its reduced row echelon basis (h x n); ordered by pivot set (lexicographic), then by free entries (row-major, lexicographic).\"}, {\"lean\": \"allMatrices\", \"member\": \"gfp.matrix\", \"name\": \"all_matrices\", \"summary\": \"Every rows x cols matrix over F_p; index is the row-major base-p number of the entries.\"}, {\"lean\": \"transform\", \"member\": \"gfp.matrix\", \"name\": \"transform\", \"summary\": \"Each member M of the inner family replaced by M * C for a fixed matrix C. Same order and indices.\"}, {\"lean\": \"stack\", \"member\": \"gfp.matrix\", \"name\": \"stack\", \"summary\": \"Each member M of the inner family with a fixed block of rows appended below it. Same order and indices.\"}, {\"lean\": \"groupElements\", \"member\": \"orbits.perms\", \"name\": \"group_elements\", \"summary\": \"Every element of the permutation group generated by the given orbits.perms, as a 1 x n permutation, in lexicographic order of the image list. Size is the group order.\"}, {\"lean\": \"subsetsOf\", \"member\": \"gfp.matrix\", \"name\": \"subsets_of\", \"summary\": \"Every k-subset of the members of an inner family, each member flattened to one row of rows*cols entries, indices increasing; lexicographic order of the index tuple. The inner family is materialised once and must have at most 2^22 members.\"}, {\"lean\": \"symmetricMatrices\", \"member\": \"gfp.matrix\", \"name\": \"symmetric_matrices\", \"summary\": \"Every symmetric n x n matrix over F_p; index is the base-p number of the upper triangle read row-major.\"}, {\"lean\": \"range\", \"member\": \"lk.naturals\", \"name\": \"range\", \"summary\": \"The integers a <= x < b as 1 x 1 natural-number matrices; index is x - a.\"}, {\"lean\": \"words\", \"member\": \"lk.naturals\", \"name\": \"words\", \"summary\": \"Every word of the given length over the alphabet 0..alphabet-1 as a 1 x length natural-number matrix; index is the base-alphabet number of the word.\"}], \"reductions\": [{\"accepts\": [\"*\"], \"name\": \"all\", \"summary\": \"Materialise the per-member value for every member, in family order. Integers and booleans come back as kind `integers`.\"}, {\"accepts\": [\"boolean\"], \"name\": \"count\", \"summary\": \"Number of members whose value is true (kind `count`: value, visited, family_size).\"}, {\"accepts\": [\"integer\"], \"name\": \"histogram\", \"summary\": \"Number of members per value (kind `histogram`: u64 bins[0..max]).\"}, {\"accepts\": [\"boolean\"], \"args\": {\"limit\": \"int\"}, \"name\": \"hits\", \"summary\": \"Canonical indices of every member whose value is true, and the first `limit` of them materialised (kind `hits`).\"}, {\"accepts\": [\"boolean\"], \"name\": \"first\", \"summary\": \"The least canonical index whose value is true, materialised, or found = 0 when there is none (kind `first`). Stops as soon as nothing below the best hit remains; `visited` is index + 1 when found and family_size otherwise.\"}, {\"accepts\": [\"integer\"], \"name\": \"sum\", \"summary\": \"Sum of the values over the family (kind `count`: value, visited, family_size); fails if it exceeds 2^64 - 1.\"}, {\"accepts\": [\"integer\"], \"name\": \"max\", \"summary\": \"The largest value and the least index attaining it, materialised (kind `extremum`).\"}, {\"accepts\": [\"integer\"], \"name\": \"min\", \"summary\": \"The smallest value and the least index attaining it, materialised (kind `extremum`).\"}]}}";
